const JS="(()=>{\n'use strict';\nconst IS_PREDICTIONS=location.pathname.startsWith('/predictions');\nif(!IS_PREDICTIONS)return; // this controller must never initialize homepage-only DOM.\nconst $=(s,root=document)=>root.querySelector(s);\nconst $$=(s,root=document)=>Array.from(root.querySelectorAll(s));\nconst esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n\nconst ICON_PATHS={\"star\":\"<path d=\\\"m12 2 3.1 6.5 7.2 1-5.2 5 1.2 7-6.3-3.5-6.3 3.5 1.2-7-5.2-5 7.2-1z\\\"/>\",\"calendarOff\":\"<path d=\\\"M10 3v4M17 3v4M3 10h18\\\"/><rect x=\\\"3\\\" y=\\\"5\\\" width=\\\"18\\\" height=\\\"16\\\" rx=\\\"2\\\"/><path d=\\\"m3 3 18 18\\\"/>\",\"info\":\"<circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"10\\\"/><path d=\\\"M12 11v6M12 7h.01\\\"/>\",\"shield\":\"<path d=\\\"M12 2 4 6v6c0 5 3.8 8 8 10 4.2-2 8-5 8-10V6z\\\"/><path d=\\\"m9 12 2 2 4-4\\\"/>\",\"layers\":\"<path d=\\\"m12 2 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 17l9 5 9-5\\\"/>\",\"alert\":\"<circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"10\\\"/><path d=\\\"M12 7v6m0 4h.01\\\"/>\",\"check\":\"<circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"10\\\"/><path d=\\\"m7 12 3.3 3.3L17 9\\\"/>\",\"chevron\":\"<path d=\\\"m9 18 6-6-6-6\\\"/>\"};\nfunction icon(name,extra=''){return '<svg class=\"ui-icon'+(extra?' '+extra:'')+'\" aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">'+(ICON_PATHS[name]||ICON_PATHS.info)+'</svg>'}\nfunction skel(cls){return '<span class=\"skel '+cls+'\" aria-hidden=\"true\"></span>'}\nfunction pairPreferred(a,b){return num(a)!==null&&num(b)!==null&&a>=0&&a<=100&&b>=0&&b<=100&&a!==b?(a>b?0:1):-1}\nfunction renderLoading(){\n  document.body.classList.add('is-loading');\n  const side=$('#sidebarLeagues'),mobile=$('#mobileLeagues'),dates=$('#dateTabs');\n  if(IS_PREDICTIONS){\n    if(side){side.setAttribute('aria-busy','true');side.innerHTML=Array.from({length:6},()=>'<div class=\"skel-league\">'+skel('skel-circle')+skel('skel-line')+'</div>').join('')}\n    if(mobile){mobile.setAttribute('aria-busy','true');mobile.innerHTML=Array.from({length:4},()=>skel('skel-tab')).join('')}\n    if(dates){dates.setAttribute('aria-busy','true');dates.innerHTML=Array.from({length:5},()=>skel('skel-date')).join('')}\n    if($('#matchesCount'))$('#matchesCount').innerHTML=skel('skel-line');\n    const rows=$('#matchRows');\n    if(rows){rows.innerHTML=Array.from({length:6},()=>'<tr class=\"skel-table-row\"><td>'+skel('skel-time')+'</td><td>'+skel('skel-small-circle')+'</td><td><div class=\"skel-team-group\">'+skel('skel-small-circle')+skel('skel-fixture')+'</div></td>'+Array.from({length:6},()=>'<td>'+skel('skel-probcell')+'</td>').join('')+'<td>'+skel('skel-small-circle')+'</td></tr>').join('');rows.setAttribute('aria-busy','true')}\n    if($('#loadMore'))$('#loadMore').hidden=true;\n    if($('#feedStatus'))$('#feedStatus').innerHTML=skel('skel-line');\n  }else{\n    for(const id of ['metricMatches','metricLeagues','metricAnalyses']){const el=$('#'+id);if(el)el.innerHTML=skel('skel-metric')}\n    for(const id of ['spotLeague','spotDate','spotLabel']){const el=$('#'+id);if(el)el.innerHTML=skel('skel-line')}\n    for(const id of ['spotHome','spotAway']){const el=$('#'+id);if(el)el.innerHTML=skel('skel-crest')+skel('skel-team')}\n    if($('#spotForm'))$('#spotForm').innerHTML='<div class=\"form-empty-inner\">'+skel('skel-line')+'</div>';\n    if($('#spotPred'))$('#spotPred').innerHTML=Array.from({length:3},()=>'<div class=\"feature-prob skel-prob\">'+skel('skel-line')+skel('skel-num')+skel('skel-track')+'</div>').join('');\n    if($('#spotMarkets'))$('#spotMarkets').innerHTML=Array.from({length:4},()=>'<div class=\"market skel-market\">'+skel('skel-line')+skel('skel-num')+'</div>').join('');\n    if($('#statsHome'))$('#statsHome').innerHTML=skel('skel-line');\n    if($('#statsAway'))$('#statsAway').innerHTML=skel('skel-line');\n    if($('#statsCompare'))$('#statsCompare').innerHTML=Array.from({length:3},()=>'<div class=\"skel-stat\">'+skel('skel-value')+skel('skel-label')+skel('skel-value')+'</div>').join('');\n    const upcoming=$('#upcomingGrid');\n    if(upcoming){upcoming.innerHTML=Array.from({length:3},()=>'<div class=\"upcoming-card upcoming-skeleton\"><div class=\"upcoming-card-head\">'+skel('skel-line')+skel('skel-time')+'</div><div class=\"upcoming-teams\">'+skel('skel-circle')+skel('skel-fixture')+skel('skel-circle')+'</div>'+skel('skel-probcell')+'</div>').join('');upcoming.setAttribute('aria-busy','true')}\n    if($('#spotDetails'))$('#spotDetails').disabled=true;\n    if($('#statsAnalyze'))$('#statsAnalyze').disabled=true;\n  }\n  for(const id of ['featured','statsCompare','spotPred','spotMarkets'])$('#'+id)?.setAttribute('aria-busy','true');\n}\nfunction finishLoading(){document.body.classList.remove('is-loading');for(const id of ['sidebarLeagues','mobileLeagues','dateTabs','matchRows','featured','statsCompare','spotPred','spotMarkets','upcomingGrid'])$('#'+id)?.setAttribute('aria-busy','false')}\nfunction formEmpty(){return '<div class=\"form-empty-inner\" role=\"status\">'+icon('calendarOff')+'<span>Δεν υπάρχουν διαθέσιμα στοιχεία πρόσφατης φόρμας</span></div>'}\n\nconst LEAGUES={ucl:['UEFA Champions League','UCL'],uel:['UEFA Europa League','UEL'],uecl:['UEFA Conference League','UECL'],epl:['Premier League','PL'],laliga:['La Liga','LL'],bundesliga:['Bundesliga','BL'],seriea:['Serie A','SA'],ligue1:['Ligue 1','L1'],greece:['Greek Super League','GSL'],cyprus:['Cyprus First Division','CYP']};\nconst CRESTS={'Chelsea FC':61,'Everton FC':62,'Liverpool FC':64,'Manchester City FC':65,'Manchester United FC':66,'Arsenal FC':57,'Tottenham Hotspur FC':73,'Newcastle United FC':67,'Aston Villa FC':58,'West Ham United FC':563,'Borussia Dortmund':4,'FC Bayern München':5,'Bayer 04 Leverkusen':3,'RB Leipzig':721,'VfB Stuttgart':10,'Eintracht Frankfurt':19,'SSC Napoli':113,'AC Milan':98,'Juventus FC':109,'FC Internazionale Milano':108,'AS Roma':100,'FC Barcelona':81,'Real Madrid CF':86,'Club Atlético de Madrid':78,'Paris Saint-Germain FC':524,'Olympique de Marseille':516,'Olympique Lyonnais':523,'AS Monaco FC':548};\nconst STORAGE='tiki-data-favorites-v13';\nfunction readFavorites(){try{return new Set(JSON.parse(localStorage.getItem(STORAGE)||'[]').map(String))}catch{return new Set()}}\nconst params=new URLSearchParams(location.search);\nconst allowedFilters=new Set(['all','predicted','favorites','live']);\nconst initialSource='verified';\nconst isoDateShift=n=>{const x=new Date();x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10);};\nconst state={all:[],base:[],liveMatches:new Map(),liveUpdatedAt:null,liveFetchBusy:false,source:initialSource,apiDate:/^\\d{4}-\\d{2}-\\d{2}$/.test(params.get('date')||'')?params.get('date'):isoDateShift(0),leagueImages:new Map(),requestId:0,league:'all',day:'all',mode:IS_PREDICTIONS&&allowedFilters.has(params.get('filter'))?params.get('filter'):'all',query:IS_PREDICTIONS?String(params.get('q')||'').trim().toLocaleLowerCase():'',limit:100,selectedId:null,featuredId:null,feed:'loading',error:'',favorites:readFavorites(),modalRestore:null};\nconst lname=s=>LEAGUES[s]?.[0]||String(s||'Άλλη διοργάνωση').replace(/[-_]/g,' ');\nconst labbr=s=>LEAGUES[s]?.[1]||String(s||'').slice(0,3).toUpperCase();\nconst num=v=>typeof v==='number'&&Number.isFinite(v)?v:null;\nconst pct=v=>num(v)===null?'—':v.toLocaleString('el-GR',{maximumFractionDigits:1})+'%';\nconst kt=d=>{const x=new Date(d);return Number.isNaN(+x)?'unknown':x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')};\nconst dateFmt=(d,mode='short')=>new Intl.DateTimeFormat('el-GR',mode==='full'?{weekday:'long',day:'numeric',month:'long'}:mode==='weekday'?{weekday:'short',day:'numeric',month:'short'}:{day:'2-digit',month:'2-digit'}).format(new Date(d));\nconst clock=d=>new Intl.DateTimeFormat('el-GR',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(d));\nconst inProgress=m=>['LIVE','1H','2H','1ST','2ND','HT','ET','BREAK','1ST_HALF','2ND_HALF','HALF_TIME'].includes(String(m?.status||'').toUpperCase());\nconst liveForecast=m=>m?.live_outlook||m?.live_prediction||null;\nconst liveForecastSource=m=>m?.live_outlook?'TIKI-DATA LIVE · ΠΕΙΡΑΜΑΤΙΚΟ':m?.live_prediction?'SPORTMONKS LIVE · 1Χ2':'LIVE ΧΩΡΙΣ ΔΙΑΘΕΣΙΜΗ ΠΙΘΑΝΟΤΗΤΑ';\nfunction tierLabel(m){\n const tier=m?.prediction_tier;\n if(tier==='team')return 'ΟΜΑΔΙΚΑ ΔΕΔΟΜΕΝΑ · ΠΕΙΡΑΜΑΤΙΚΟ';\n if(tier==='partial_team')return 'ΜΕΡΙΚΟ ΙΣΤΟΡΙΚΟ ΟΜΑΔΩΝ · ΧΑΜΗΛΗ ΒΕΒΑΙΟΤΗΤΑ';\n if(tier==='league')return 'ΜΕΣΟΙ ΟΡΟΙ ΠΡΩΤΑΘΛΗΜΑΤΟΣ · ΧΑΜΗΛΗ ΒΕΒΑΙΟΤΗΤΑ';\n if(tier==='cross_league')return 'ΓΕΝΙΚΗ ΙΣΤΟΡΙΚΗ ΒΑΣΗ · ΠΟΛΥ ΧΑΜΗΛΗ ΒΕΒΑΙΟΤΗΤΑ';\n return 'ΧΩΡΙΣ ΔΙΑΘΕΣΙΜΗ ΕΚΤΙΜΗΣΗ';\n}\nfunction tierExplanation(m){\n if(m.prediction_tier==='cross_league')return 'Το συγκεκριμένο πρωτάθλημα δεν έχει αρκετά ιστορικά αποτελέσματα στη βάση. Το 1Χ2 και τα γκολ προκύπτουν από μέσους όρους άλλων αδειοδοτημένων πρωταθλημάτων. Δεν είναι πρόβλεψη βασισμένη στη δυναμικότητα των συγκεκριμένων ομάδων.';\n if(m.prediction_tier==='league')return 'Οι πιθανότητες υπολογίζονται από την πραγματική κατανομή σκορ του πρωταθλήματος. Δεν χρησιμοποιούνται επαρκή προσωπικά στοιχεία των ομάδων.';\n if(m.prediction_tier==='partial_team')return 'Μόνο η μία ομάδα έχει αντιστοιχισμένο ιστορικό έδρας/εκτός. Η άλλη εκπροσωπείται από τον ιστορικό μέσο όρο του πρωταθλήματος.';\n if(m.prediction_tier==='team')return 'Υπάρχουν ιστορικά δεδομένα και των δύο ομάδων για τη συγκεκριμένη έδρα/εκτός. Το αποτέλεσμα παραμένει πειραματικό.';\n return 'Δεν υπάρχουν αρκετά επαληθευμένα δεδομένα για αριθμητική πρόβλεψη.';\n}\nfunction valid(m){return [m.p1,m.px,m.p2].every(v=>num(v)!==null&&v>=0&&v<=100)&&Math.abs(m.p1+m.px+m.p2-100)<2}\n/* Club/league image catalog is built from already verified D1 mappings. */\nconst LOGO_CATALOG=window.TIKI_LOGO_CATALOG||{teams:{},leagues:{}};\nconst sportmonksLogo=u=>typeof u==='string'&&/^https:\\/\\/cdn\\.sportmonks\\.com\\/images\\/[\\w/%.-]{1,190}\\.(?:png|jpe?g|webp|svg)$/i.test(u)?u:null;\nconst safeSignedLogo=u=>typeof u==='string'&&/^\\/api\\/logo\\/team\\/\\d{1,13}\\?sig=[0-9a-f]{64}$/.test(u)?u:null;\nfunction verifiedLeagueLogo(name){const t=String(name||'').toLowerCase();const l=window.TIKI_LOGO_CATALOG?.leagues||{};const key=/(?:premier league|english premier)/i.test(t)?'epl':/bundesliga/i.test(t)?'bundesliga':/(?:la liga|laliga|primera divisi)/i.test(t)?'laliga':/serie a/i.test(t)?'seriea':/(?:ligue 1|ligue1)/i.test(t)?'ligue1':/(?:super league.*gree|greek super|greece.*super)/i.test(t)?'greece':null;return key?l[key]||null:null;}\nconst logoNorm=s=>String(s||'').normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^\\p{L}\\p{N}]+/gu,' ').trim().toLowerCase();\nconst safeLogo=u=>typeof u==='string'&&/^https:\\/\\/(?:raw\\.githubusercontent\\.com|media\\.api-sports\\.io)\\//.test(u)?u:null;\nconst allSportsLogo=u=>typeof u==='string'&&/^https:\\/\\/(?:apiv2\\.)?allsportsapi\\.com\\/logo\\/[a-zA-Z0-9_./%-]{1,180}\\.(?:png|jpe?g|webp)$/i.test(u)?u:null;\nconst teamImages=new Map(),shortImages=new Map();\nconst shorten=s=>logoNorm(s).replace(/\\b(?:fc|afc|cf|sc|ac)\\b/g,'').replace(/\\s+/g,' ').trim();\nfor(const [name,href] of Object.entries(LOGO_CATALOG.teams||{})){const u=safeLogo(href);if(!u)continue;teamImages.set(logoNorm(name),u);const short=shorten(name);if(shortImages.has(short)&&shortImages.get(short)!==u)shortImages.set(short,null);else if(!shortImages.has(short))shortImages.set(short,u)}\nconst teamAliases=new Map([['olympiacos piraeus','olympiakos piraeus'],['olympiacos','olympiakos piraeus'],['bayern munich','fc bayern munchen'],['bayern münchen','fc bayern munchen'],['valencia','valencia cf'],['real madrid','real madrid cf'],['sevilla','sevilla fc'],['sunderland','sunderland afc'],['bournemouth','afc bournemouth'],['athletic bilbao','athletic club'],['panathinaikos fc','panathinaikos'],['asteras tripolis fc','asteras tripolis'],['panetolikos fc','panetolikos']]);\nfunction realTeamLogo(name){const key=logoNorm(name);return teamImages.get(key)||teamImages.get(teamAliases.get(key))||shortImages.get(shorten(name))||null}\nfunction logoImage(url,cls='logo-image'){return '<img class=\"'+esc(cls)+'\" src=\"'+esc(url)+'\" alt=\"\" loading=\"lazy\" decoding=\"async\" referrerpolicy=\"no-referrer\">'}\nfunction crest(name,cls='table-crest',providerURL=null){\n const n=String(name||''),initials=n.replace(/\\b(fc|cf|sc|ac|afc|sv|club)\\b/gi,'').trim().split(/\\s+/).slice(0,2).map(a=>a[0]||'').join('').toUpperCase()||'FC';\n const verified=realTeamLogo(n),provider=sportmonksLogo(providerURL),hasReal=!!(verified||provider);\n return '<span class=\"'+esc(cls)+(hasReal?' has-team-logo':' team-no-logo')+'\" title=\"'+esc(n)+'\" aria-label=\"Έμβλημα '+esc(n)+'\"><span class=\"team-initials\">'+esc(initials)+'</span>'\n +(verified?logoImage(verified,'logo-image team-logo-image'):'')\n +(provider&&provider!==verified?logoImage(provider,'logo-image team-logo-image'):'')+'</span>';\n}\nfunction competition(s,cls='small-league',key=null){const logo=sportmonksLogo(state.leagueImages.get(s))||safeLogo(LOGO_CATALOG.leagues?.[key]||LOGO_CATALOG.leagues?.[s]||verifiedLeagueLogo(s));const short=labbr(s);return '<span class=\"'+esc(cls)+(logo?' has-real-logo':'')+'\" title=\"'+esc(lname(s))+'\" data-short=\"'+esc(short)+'\">'+(logo?logoImage(logo,'logo-image league-image'):'<span class=\"league-fallback\">'+esc(short)+'</span>')+'</span>'}\nfunction filteredBase(){let list=state.all.filter(m=>(state.league==='all'||m.league===state.league)&&(state.mode!=='predicted'||(valid(m)&&m.coverage!=='no_team_specific_evidence'))&&(state.mode!=='favorites'||state.favorites.has(String(m.id)))&&(state.mode!=='live'||inProgress(m))&&(!state.query||(m.home+' '+m.away+' '+lname(m.league)).toLocaleLowerCase().includes(state.query)));return list}\nfunction filtered(){return filteredBase().filter(m=>state.day==='all'||kt(m.date)===state.day)}\nfunction hasFilters(){return state.league!=='all'||state.day!=='all'||state.mode!=='all'||!!state.query}\nfunction syncSearch(){for(const s of ['#globalSearch','#fixtureSearch']){const el=$(s);if(el&&el.value!==state.query)el.value=state.query}}\nfunction resetAllFilters(){\n state.league='all';state.day='all';state.mode='all';state.query='';state.limit=100;\n try{history.replaceState(null,'',location.pathname)}catch{}\n syncSearch();update();\n}\nfunction setMode(next){if(!IS_PREDICTIONS){location.href='/predictions?filter='+encodeURIComponent(next);return}if(next==='all'){resetAllFilters();return}state.mode=next;state.limit=100;state.day='all';update()}\nfunction setLeague(next){if(!IS_PREDICTIONS){location.href='/predictions';return}if(next==='all'){resetAllFilters();return}state.league=next;state.mode='all';state.day='all';state.query='';state.limit=100;syncSearch();update()}\nfunction setDay(next){state.day=next;state.limit=100;update()}\nfunction renderFilterNotice(){\n const panel=$('#filterNotice');if(!panel)return;\n panel.hidden=!hasFilters();if(panel.hidden)return;\n const parts=[];if(state.league!=='all')parts.push(lname(state.league));\n if(state.mode==='favorites')parts.push('Αγαπημένα');else if(state.mode==='predicted')parts.push('Με αριθμητική πρόβλεψη');else if(state.mode==='live')parts.push('Ζωντανοί αγώνες');\n if(state.day!=='all')parts.push('Συγκεκριμένη ημέρα');\n if(state.query)parts.push('Αναζήτηση: '+state.query);\n $('#filterNoticeText').textContent='Ενεργά φίλτρα: '+parts.join(' · ');\n}\nfunction renderLeagues(){if(!IS_PREDICTIONS)return;if($('#sideFavCount'))$('#sideFavCount').textContent=String(state.favorites.size);const leagues=[...new Set(state.all.map(m=>m.league))].sort((a,b)=>lname(a).localeCompare(lname(b),'el'));const total=state.all.length;\n$('#sidebarLeagues').innerHTML='<button class=\"side-league'+(state.league==='all'?' selected':'')+'\" data-league=\"all\" aria-pressed=\"'+(state.league==='all')+'\"><span class=\"league-badge\">ALL</span><span class=\"lname\">Όλες οι διοργανώσεις</span><span class=\"side-count\">'+total+'</span></button>'+leagues.map(s=>'<button class=\"side-league'+(state.league===s?' selected':'')+'\" data-league=\"'+esc(s)+'\" aria-pressed=\"'+(state.league===s)+'\">'+competition(s,'league-badge',state.all.find(m=>m.league===s)?.league_key)+'<span class=\"lname\">'+esc(lname(s))+'</span><span class=\"side-count\">'+state.all.filter(m=>m.league===s).length+'</span></button>').join('');\nconst scroller=$('#mobileLeagues'),scroll=scroller.scrollLeft;\nscroller.innerHTML='<button class=\"league-tab'+(state.league==='all'?' selected':'')+'\" data-league=\"all\" aria-pressed=\"'+(state.league==='all')+'\"><span class=\"tab-league\">ALL</span> Όλες <small>'+total+'</small></button>'+leagues.map(s=>'<button class=\"league-tab'+(state.league===s?' selected':'')+'\" data-league=\"'+esc(s)+'\" aria-pressed=\"'+(state.league===s)+'\">'+competition(s,'tab-league',state.all.find(m=>m.league===s)?.league_key)+' '+esc(lname(s))+' <small>'+state.all.filter(m=>m.league===s).length+'</small></button>').join('');\nscroller.scrollLeft=scroll;\n}\nfunction renderDates(){if(!IS_PREDICTIONS)return;\n const base=filteredBase(),today=kt(new Date()),tomorrow=kt(new Date(Date.now()+86400000));\n const days=[...new Map(base.map(m=>[kt(m.date),m.date])).entries()].filter(x=>x[0]!=='unknown').sort((a,b)=>a[0].localeCompare(b[0]));\n const rail=$('#dateTabs'),scroll=rail.scrollLeft;\n rail.innerHTML='<button class=\"day-btn'+(state.day==='all'?' selected':'')+'\" data-day=\"all\" aria-pressed=\"'+(state.day==='all')+'\"><strong>Όλες</strong>οι ημέρες</button>'+\n days.map(([key,raw])=>'<button class=\"day-btn'+(state.day===key?' selected':'')+'\" data-day=\"'+esc(key)+'\" aria-pressed=\"'+(state.day===key)+'\"><strong>'+esc(key===today?'Σήμερα':key===tomorrow?'Αύριο':dateFmt(raw,'weekday'))+'</strong>'+esc(new Date(raw).toLocaleDateString('el-GR',{day:'numeric',month:'short'}))+'</button>').join('');\n rail.scrollLeft=scroll;\n const pick=$('#desktopDatePick');if(pick)pick.value=state.day==='all'?'':state.day;\n}\nfunction drawMode(){ $$('[data-quick]').forEach(el=>{const on=el.dataset.quick===state.mode;el.classList.toggle('is-active',on);el.classList.toggle('active',on);el.classList.toggle('selected',on)});$$('[data-nav]').forEach(el=>el.classList.toggle('nav-current',el.dataset.nav===(IS_PREDICTIONS?'predictions':'home')))}\nfunction renderStatsSummary(){if(IS_PREDICTIONS)return;const ready=state.all.filter(valid).length;$('#metricMatches').textContent=String(state.all.length);$('#metricLeagues').textContent=String(new Set(state.all.map(m=>m.league)).size);$('#metricAnalyses').textContent=String(ready);if($('#sideFavCount'))$('#sideFavCount').textContent=String(state.favorites.size)}\nfunction marketPill(title,p,highlight=false){return '<div class=\"market'+(highlight?' strongest':'')+'\"><small>'+esc(title)+'</small><b>'+esc(pct(p))+'</b></div>'}\nfunction renderFeatured(){if(IS_PREDICTIONS)return;$('#spotForm').innerHTML=formEmpty();const a=state.all.filter(m=>Date.parse(m.date)>=Date.now());const selected=a.find(x=>String(x.id)===String(state.featuredId))||a.find(valid)||a[0];if(!selected){$('#spotLabel').textContent='NO UPCOMING MATCH';$('#spotLeague').textContent='Χωρίς αγώνα';$('#spotHome').innerHTML=crest('','featured-crest')+'<b>—</b>';$('#spotAway').innerHTML=crest('','featured-crest')+'<b>—</b>';$('#spotDate').textContent='—';$('#spotPred').innerHTML='<div class=\"feature-prob muted\">'+icon('info')+' Δεν υπάρχει διαθέσιμος αγώνας.</div>';$('#spotMarkets').innerHTML='';$('#statsHome').textContent='HOME';$('#statsAway').textContent='AWAY';$('#statsCompare').innerHTML='';$('#spotDetails').disabled=true;$('#statsAnalyze').disabled=true;return}\nstate.featuredId=String(selected.id);$('#spotDetails').disabled=false;$('#statsAnalyze').disabled=false;\n$('#spotLeague').innerHTML=competition(selected.league,'small-league',selected.league_key)+'<span>'+esc(lname(selected.league))+'</span>';$('#spotDate').textContent=dateFmt(selected.date,'weekday')+' · '+clock(selected.date);$('#spotLabel').textContent=valid(selected)?'MODEL AVAILABLE':'UPCOMING';$('#spotHome').innerHTML=crest(selected.home,'featured-crest')+'<b>'+esc(selected.home)+'</b>';$('#spotAway').innerHTML=crest(selected.away,'featured-crest')+'<b>'+esc(selected.away)+'</b>';\nconst probs=[selected.p1,selected.px,selected.p2];const best=valid(selected)?Math.max(...probs):null;\n$('#spotPred').innerHTML=valid(selected)?probs.map((p,i)=>'<div class=\"feature-prob'+(p===best?' best strongest':'')+'\"><div><small>'+['1','X','2'][i]+'</small><b>'+esc(pct(p))+'</b></div><span class=\"track\"><i style=\"width:'+Math.max(0,Math.min(p,100))+'%\"></i></span></div>').join(''):'<div class=\"feature-prob muted\">Δεν υπάρχουν επαρκή δεδομένα για πρόβλεψη 1Χ2.</div>';\nconst ouBest=pairPreferred(selected.over25,selected.under25),bttsBest=pairPreferred(selected.btts,selected.no_btts);$('#spotMarkets').innerHTML=marketPill('Over 2.5',selected.over25,ouBest===0)+marketPill('Under 2.5',selected.under25,ouBest===1)+marketPill('BTTS · Ναι',selected.btts,bttsBest===0)+marketPill('BTTS · Όχι',selected.no_btts,bttsBest===1);\n$('#statsHome').textContent=selected.home;$('#statsAway').textContent=selected.away;\nconst stats=[['Αναμενόμενα γκολ',selected.mu_home,selected.mu_away],['Κατοχή μπάλας',null,null],['Σουτ στον στόχο',null,null]];\n$('#statsCompare').innerHTML=stats.map(([lab,l,r])=>{const have=num(l)!==null&&num(r)!==null,sum=have?l+r:0,L=sum>0?Math.round(l/sum*100):50;return '<div class=\"stat-row\"><span class=\"stat-val\">'+(have?l.toFixed(2):'—')+'</span><div class=\"stat-row-mid\"><span>'+esc(lab)+'</span><div class=\"stat-track\"><i style=\"width:'+(have?L:0)+'%\"></i><b style=\"width:'+(have?100-L:0)+'%\"></b></div></div><span class=\"stat-val\">'+(have?r.toFixed(2):'—')+'</span></div>'}).join('');\n}\nfunction outcome(value,best){const v=num(value);return '<span class=\"pct'+(v===null?' na':best?' best strongest':'')+'\"'+(best?' title=\"Υψηλότερη πιθανότητα στην κατηγορία\"':'')+'>'+esc(pct(v))+'</span>'}\nfunction summaryInsight(m){\n const p=inProgress(m)?liveForecast(m):valid(m)?m:null;\n if(inProgress(m)){\n  const s=(num(m.home_score)!==null&&num(m.away_score)!==null)?m.home_score+'–'+m.away_score:'σκορ προς ενημέρωση';\n  return 'LIVE '+(num(m.minute)!==null?m.minute+'′ · ':'')+s+' · '+(m.live_outlook?'Σενάρια εξέλιξης διαθέσιμα':m.live_prediction?'Live 1Χ2 από Sportmonks':'Γεγονότα και στατιστικά χωρίς μοντελοποιημένες πιθανότητες');\n }\n if(!p)return 'Πραγματικό πρόγραμμα · ανεπαρκές αντιστοιχισμένο ιστορικό ομάδων για ποσοστά';\n const vals=[p.p1,p.px,p.p2],idx=vals.indexOf(Math.max(...vals));\n return 'Πιθανότερο 1Χ2: '+['1','Χ','2'][idx]+' ('+pct(vals[idx])+') · '+tierLabel(m)+' · '+\n  (num(m.mu_home)!==null&&num(m.mu_away)!==null?' · Αναμενόμενα γκολ '+m.mu_home.toFixed(2)+'–'+m.mu_away.toFixed(2):'');\n}\nfunction renderOverview(){\n const n=id=>$(id);\n if(!n('#overviewMatches'))return;\n n('#overviewMatches').textContent=String(state.all.length);\n n('#overviewLive').textContent=String(state.all.filter(inProgress).length);\n const estimates=state.all.filter(m=>valid(m)&&!inProgress(m));\n n('#overviewPredicted').textContent=String(estimates.length);\n if(n('#overviewPredictedDetail')){\n  const fitted=estimates.filter(m=>m.prediction_tier==='team').length;\n  n('#overviewPredictedDetail').textContent=fitted+' πλήρεις · '+(estimates.length-fitted)+' βασικές';\n }\n n('#overviewUpdated').textContent=state.liveUpdatedAt?'Live ενημέρωση: '+new Date(state.liveUpdatedAt).toLocaleTimeString('el-GR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'Αναμονή live ροής…';\n}\nfunction reconcileMatches(){\n const data=new Map(state.base.map(x=>[String(x.id),x]));\n for(const [id,m] of state.liveMatches){\n  const orig=data.get(id);\n  data.set(id,orig?{...orig,...m,logos:{...(orig.logos||{}),...(m.logos||{})}}:m);\n }\n state.all=[...data.values()].filter(m=>m?.id&&m.home&&m.away&&m.date&&Number.isFinite(Date.parse(m.date)))\n  .sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));\n state.leagueImages=new Map(state.all.filter(m=>sportmonksLogo(m.league_logo)).map(m=>[m.league,m.league_logo]));\n}\nasync function refreshLive(){\n if(!IS_PREDICTIONS||document.hidden||state.liveFetchBusy)return;\n state.liveFetchBusy=true;\n try{\n  const res=await fetch('/api/live',{cache:'no-store',headers:{Accept:'application/json'}});\n  if(!res.ok)throw Error('live_feed_unavailable');\n  const d=await res.json();\n  if(!Array.isArray(d.matches))throw Error('live_feed_invalid');\n  state.liveMatches=new Map(d.matches.filter(m=>m?.id&&m.home&&m.away).map(m=>[String(m.id),m]));\n  state.liveUpdatedAt=d.updated_at||new Date().toISOString();\n  reconcileMatches();\n  if(state.feed==='ready'){\n   update();\n   if(state.selectedId&&$('#modalMount')?.innerHTML)showModal(state.selectedId,true);\n  }\n }catch{if($('#overviewUpdated')&&!state.liveUpdatedAt)$('#overviewUpdated').textContent='Η live ενημέρωση δεν είναι διαθέσιμη';}\n finally{state.liveFetchBusy=false}\n}\nfunction matchLine(m){const probability=inProgress(m)?liveForecast(m):valid(m)?m:null;const p=probability?[probability.p1,probability.px,probability.p2]:[null,null,null],max=p.every(x=>x!==null)?Math.max(...p):null,bt=num(inProgress(m)?m.live_outlook?.btts:m.btts),nb=num(inProgress(m)?null:m.no_btts),o=num(inProgress(m)?m.live_outlook?.over25:m.over25),u=num(inProgress(m)?m.live_outlook?.under25:m.under25),ouBest=pairPreferred(o,u),btBest=pairPreferred(bt,nb),fav=state.favorites.has(String(m.id));const quality=inProgress(m)?liveForecastSource(m):valid(m)?tierLabel(m):'ΕΠΑΛΗΘΕΥΜΕΝΟΣ ΑΓΩΝΑΣ · ΠΕΡΙΟΡΙΣΜΕΝΑ ΣΤΟΙΧΕΙΑ';const briefing=summaryInsight(m);\nconst mobile='<article class=\"td-mobile-card\"><div class=\"td-mobile-meta\">'+competition(m.league,'small-league',m.league_key)+'<span class=\"td-mobile-league\">'+esc(lname(m.league))+'</span><time>'+(inProgress(m)?'● LIVE '+(num(m.home_score)!==null&&num(m.away_score)!==null?esc(m.home_score+'–'+m.away_score):''):esc(clock(m.date)))+'</time></div>'\n+'<div class=\"td-mobile-teams\"><div class=\"td-mobile-team\">'+crest(m.home,'table-crest',m.logos?.home)+'<span class=\"td-mobile-name\">'+esc(m.home)+'</span></div><span class=\"td-mobile-vs\">'+(inProgress(m)&&num(m.home_score)!==null?esc(m.home_score+'–'+m.away_score):'VS')+'</span><div class=\"td-mobile-team\">'+crest(m.away,'table-crest',m.logos?.away)+'<span class=\"td-mobile-name\">'+esc(m.away)+'</span></div></div>'\n+'<div class=\"td-mobile-probs\"><span>1 <b>'+pct(p[0])+'</b></span><span>Χ <b>'+pct(p[1])+'</b></span><span>2 <b>'+pct(p[2])+'</b></span></div><div class=\"td-mobile-extras\"><span>Over 2.5 <b>'+pct(o)+'</b></span><span>GG <b>'+pct(bt)+'</b></span></div>'\n+'<div class=\"td-mobile-insight\">'+esc(briefing)+'</div><div class=\"td-mobile-foot\"><small>'+esc(quality)+'</small><div class=\"td-mobile-actions\"><button class=\"td-mobile-detail\" data-open=\"'+esc(m.id)+'\" aria-label=\"Ανάλυση '+esc(m.home)+' εναντίον '+esc(m.away)+'\">Ανάλυση →</button><button class=\"favorite-btn'+(fav?' is-fav':'')+'\" data-favorite=\"'+esc(m.id)+'\" aria-label=\"'+(fav?'Αφαίρεση':'Προσθήκη')+' στα αγαπημένα\" aria-pressed=\"'+fav+'\">'+icon('star')+'</button></div></div></article>';\nreturn '<tr class=\"match-line\" data-match=\"'+esc(m.id)+'\"><td class=\"kickoff\">'+(inProgress(m)?'● LIVE '+(num(m.minute)!==null?m.minute+'′':''):esc(clock(m.date)))+'</td><td><span class=\"league-logo\">'+competition(m.league,'small-league',m.league_key)+'</span></td><td class=\"fixture\"><button class=\"fixture-link\" data-open=\"'+esc(m.id)+'\" aria-label=\"Ανάλυση '+esc(m.home)+' εναντίον '+esc(m.away)+'\"><span class=\"fixture-teams\"><span class=\"fixture-team home\"><span class=\"text\">'+esc(m.home)+'</span>'+crest(m.home,'table-crest',m.logos?.home)+'</span><span class=\"vs\">'+(inProgress(m)&&num(m.home_score)!==null?esc(m.home_score+'–'+m.away_score):'VS')+'</span><span class=\"fixture-team away\">'+crest(m.away,'table-crest',m.logos?.away)+'<span class=\"text\">'+esc(m.away)+'</span></span></span><small class=\"fixture-quality\">'+esc(quality)+'<br><span class=\"fixture-brief\">'+esc(briefing)+'</span>'+(m.retrospective?' · εκ των υστέρων':'')+'</small></button></td><td>'+outcome(p[0],p[0]!==null&&p[0]===max)+'</td><td>'+outcome(p[1],p[1]!==null&&p[1]===max)+'</td><td>'+outcome(p[2],p[2]!==null&&p[2]===max)+'</td><td>'+outcome(o,ouBest===0)+'</td><td>'+outcome(u,ouBest===1)+'</td><td>'+outcome(bt,btBest===0)+'</td><td><button class=\"favorite-btn'+(fav?' is-fav':'')+'\" data-favorite=\"'+esc(m.id)+'\" aria-label=\"'+(fav?'Αφαίρεση':'Προσθήκη')+' στα αγαπημένα\" aria-pressed=\"'+fav+'\">'+icon('star')+'</button></td><td class=\"mobile-match-cell\">'+mobile+'</td></tr>'}\n\n/* Home teaser: always the three chronologically next fixtures. Never invent form or fixtures. */\nfunction renderUpcoming(){\n  const root=$('#upcomingGrid');if(!root)return;\n  const soon=state.all.filter(m=>Date.parse(m.date)>=Date.now()).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date)).slice(0,3);\n  if(!soon.length){root.innerHTML='<div class=\"upcoming-empty\" role=\"status\">'+icon('info')+'<span>'+(state.error?'Το πρόγραμμα δεν είναι διαθέσιμο αυτή τη στιγμή.':'Δεν υπάρχουν καταχωρισμένοι προσεχείς αγώνες.')+'</span><a href=\"/predictions\">Άνοιγμα προγράμματος</a></div>';return}\n  root.innerHTML=soon.map(m=>{\n    const highest=valid(m)?Math.max(m.p1,m.px,m.p2):null;\n    const winner=highest===null?'Δεν υπάρχει ανάλυση':(['1','X','2'][[m.p1,m.px,m.p2].indexOf(highest)]+' · '+pct(highest));\n    return '<button class=\"upcoming-card\" data-open=\"'+esc(m.id)+'\" type=\"button\" aria-label=\"Προβολή ανάλυσης '+esc(m.home)+' εναντίον '+esc(m.away)+'\">'+\n      '<span class=\"upcoming-card-head\"><span class=\"upcoming-competition\">'+competition(m.league,'small-league',m.league_key)+'<span>'+esc(lname(m.league))+'</span></span><time datetime=\"'+esc(m.date)+'\">'+esc(dateFmt(m.date,'weekday'))+' · '+esc(clock(m.date))+'</time></span>'+\n      '<span class=\"upcoming-teams\"><span class=\"upcoming-side\">'+crest(m.home,'table-crest')+'<b>'+esc(m.home)+'</b></span><span class=\"upcoming-vs\">VS</span><span class=\"upcoming-side away\">'+crest(m.away,'table-crest')+'<b>'+esc(m.away)+'</b></span></span>'+\n      '<span class=\"upcoming-card-foot\"><span>Εκτίμηση μοντέλου</span><strong class=\"'+(highest===null?'no-prediction':'')+'\">'+esc(winner)+'</strong><span class=\"upcoming-arrow\">'+icon('chevron')+'</span></span></button>'\n  }).join('');\n}\n\nfunction mainProbabilities(m,cls='gallery-1x2'){\n const f=inProgress(m)?liveForecast(m):valid(m)?m:null;\n const vals=f?[f.p1,f.px,f.p2]:[null,null,null],max=vals.every(x=>num(x)!==null)?Math.max(...vals):null;\n return '<span class=\"'+cls+'\" aria-label=\"Πιθανότητες 1 Χ 2\">'+['1','Χ','2'].map((k,i)=>'<span class=\"g-prob'+(vals[i]!==null&&vals[i]===max?' is-leading':'')+'\"><small>'+k+'</small><strong>'+pct(vals[i])+'</strong></span>').join('')+'</span>';\n}\nfunction galleryCard(m){\n const is=inProgress(m),scoreline=is&&num(m.home_score)!==null?esc(m.home_score+' – '+m.away_score):'';\n return '<button type=\"button\" class=\"gallery-match\" data-open=\"'+esc(m.id)+'\" aria-label=\"Προβολή ανάλυσης: '+esc(m.home)+' - '+esc(m.away)+'\">'+\n '<span class=\"gallery-meta\"><span>'+competition(m.league,'small-league',m.league_key)+'<b>'+esc(lname(m.league))+'</b></span><time datetime=\"'+esc(m.date)+'\">'+(is?'● LIVE · '+esc(m.minute||'')+'′':esc(clock(m.date)))+'</time></span>'+\n '<span class=\"gallery-match-main\"><span class=\"gallery-team\">'+crest(m.home,'table-crest',m.logos?.home)+'<b>'+esc(m.home)+'</b></span>'+\n mainProbabilities(m)+'<span class=\"gallery-team\">'+crest(m.away,'table-crest',m.logos?.away)+'<b>'+esc(m.away)+'</b></span></span>'+\n (scoreline?'<span class=\"gallery-scoreline\">'+scoreline+'</span>':'')+\n '<span class=\"gallery-open\">Ανάλυση αγώνα ↗</span></button>';\n}\nfunction renderGallery(visible){\n const box=$('#matchGallery'),hero=$('#desktopMatchHero');\n if(!box||!hero)return;\n const shown=Array.isArray(visible)?visible:[];\n if(!shown.length){box.innerHTML='<p class=\"gallery-empty\">'+(state.feed==='loading'?'Φόρτωση πραγματικών αγώνων…':'Δεν υπάρχουν αγώνες για τα φίλτρα σου.')+'</p>';hero.hidden=true;return;}\n box.innerHTML=shown.map(galleryCard).join('');\n const featured=shown.find(inProgress)||shown.find(m=>Date.parse(m.date)>=Date.now())||shown[0];\n const f=inProgress(featured)?liveForecast(featured):valid(featured)?featured:null;\n hero.hidden=false;\n hero.innerHTML='<div class=\"gallery-hero-meta\"><span>FEATURED MATCH</span><strong>'+esc(lname(featured.league))+' · '+esc(dateFmt(featured.date,'full'))+' · '+esc(clock(featured.date))+'</strong></div>'+\n '<div class=\"gallery-hero-main\"><span class=\"gallery-hero-team\">'+crest(featured.home,'table-crest',featured.logos?.home)+'<strong>'+esc(featured.home)+'</strong></span>'+\n mainProbabilities(featured,'gallery-hero-odds')+\n '<span class=\"gallery-hero-team\">'+crest(featured.away,'table-crest',featured.logos?.away)+'<strong>'+esc(featured.away)+'</strong></span></div>'+\n '<div class=\"gallery-hero-footer\"><span>'+(inProgress(featured)?'● LIVE · '+(num(featured.home_score)!==null?esc(featured.home_score+' : '+featured.away_score):''):'Πειραματικές πιθανότητες · 1Χ2')+'</span>'+\n '<button type=\"button\" data-open=\"'+esc(featured.id)+'\">Πλήρης ανάλυση · Match Center ↗</button></div>';\n}\nfunction renderTable(){if(!IS_PREDICTIONS)return;const list=filtered(),shown=list.slice(0,state.limit);renderFilterNotice();renderGallery(shown);$('#matchesCount').textContent=list.length+' αγώνες';$('#loadMore').hidden=state.limit>=list.length;if(!shown.length){const message=state.error?'Δεν είναι διαθέσιμα τα δεδομένα. '+esc(state.error):state.feed==='loading'?'Φόρτωση προγράμματος…':state.all.length&&hasFilters()?'Υπάρχουν '+state.all.length+' καταχωρισμένοι αγώνες, αλλά τα ενεργά φίλτρα δεν εμφανίζουν κανέναν. <button class=\"reset-empty\" type=\"button\" data-reset-filters>Εμφάνιση όλων των αγώνων</button>':'Δεν υπάρχουν καταχωρισμένοι αγώνες για το επιλεγμένο διάστημα.';$('#matchRows').innerHTML='<tr><td colspan=\"10\" class=\"loading-cell\">'+message+'</td></tr>';return}\nlet prev=null,html='';for(const m of shown){const k=kt(m.date);if(k!==prev){html+='<tr class=\"day-divider\"><td colspan=\"10\">'+icon('calendar')+esc(dateFmt(m.date,'full'))+' <small>· '+list.filter(x=>kt(x.date)===k).length+' αγώνες</small></td></tr>';prev=k}html+=matchLine(m)}$('#matchRows').innerHTML=html}\nfunction update(){drawMode();renderOverview();if(state.feed==='loading'){renderLoading();return}finishLoading();if(IS_PREDICTIONS){renderLeagues();renderDates();renderTable()}else{renderFeatured();renderStatsSummary();renderUpcoming()}}\nfunction persistFav(){try{localStorage.setItem(STORAGE,JSON.stringify([...state.favorites]))}catch{}}\nfunction toggleFavorite(id){if(state.favorites.has(String(id)))state.favorites.delete(String(id));else state.favorites.add(String(id));persistFav();update()}\nasync function fetchFixtures(){const requestId=++state.requestId;state.feed='loading';state.error='';update();try{const url='/api/home-focus';const r=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'});const json=await r.json();if(requestId!==state.requestId)return;if(!r.ok||!Array.isArray(json.matches))throw new Error(json?.message||'Δεν επιστράφηκαν επαληθεύσιμες αναλύσεις αγώνων.');state.base=json.matches.filter(m=>m&&m.id!=null&&m.home&&m.away&&m.date&&Number.isFinite(Date.parse(m.date)));reconcileMatches();state.feed='ready';$('.status-dot')?.classList.add('connected');if($('#feedStatus'))$('#feedStatus').textContent='Δεδομένα συνδεδεμένα';update()}catch(e){if(state.requestId===requestId){state.all=[];state.base=[];state.error=String(e?.message||e).slice(0,120);state.feed='error';$('.status-dot')?.classList.remove('connected');if($('#feedStatus'))$('#feedStatus').textContent='Σφάλμα δεδομένων';update()}}}\nfunction evidenceNote(m){\n const e=m.analysis||{},sample=e.home_venue_matches??m.historical_sample?.home??0,away=e.away_venue_matches??m.historical_sample?.away??0;\n return tierExplanation(m)+' Ιστορικό: '+sample+' εντός έδρας αγώνες '+m.home+' / '+away+' εκτός έδρας '+m.away+\n '. Αγώνες του ίδιου πρωταθλήματος: '+(e.league_results??0)+'. Τελευταία ιστορική ημερομηνία: '+(e.history_latest||m.history_latest||'μη διαθέσιμο')+'.';\n}\nfunction insightNarrative(m){\n const live=inProgress(m),forecast=live?liveForecast(m):valid(m)?m:null;\n const scored=num(m.home_score)!==null&&num(m.away_score)!==null,minutes=num(m.minute);\n const notes=[];\n if(live){\n  if(scored){\n   const diff=m.home_score-m.away_score;\n   notes.push({title:'Εικόνα αγώνα',body:diff===0?'Το σκορ είναι ισόπαλο ('+m.home_score+'–'+m.away_score+'). Το αποτέλεσμα παραμένει ανοιχτό.':\n    (diff>0?m.home:m.away)+' προηγείται με '+m.home_score+'–'+m.away_score+'. Η ομάδα που χάνει χρειάζεται τουλάχιστον '+Math.abs(diff)+' γκολ για την ισοπαλία.'});\n  }else notes.push({title:'Εικόνα αγώνα',body:'Ο αγώνας είναι σε εξέλιξη. Αναμένεται έγκυρη ενημέρωση σκορ.'});\n  if(m.live_outlook)notes.push({title:'Πιθανή συνέχεια',body:'Με βάση το πραγματικό σκορ και το '+minutes+'ο λεπτό, το ανεξάρτητο Poisson εκτιμά '+Number(m.live_outlook.remaining_expected_goals.home).toFixed(2)+' γκολ για '+m.home+' και '+Number(m.live_outlook.remaining_expected_goals.away).toFixed(2)+' για '+m.away+' στον εναπομείναντα κανονικό χρόνο. Δεν λαμβάνει υπόψη κάρτες και απουσίες.'});\n  else if(m.live_prediction)notes.push({title:'Τρέχουσα πρόβλεψη',body:'Υπάρχουν live πιθανότητες 1Χ2 από το Sportmonks. Δεν υπάρχουν επαρκή δεδομένα για δική μας τεκμηριωμένη αριθμητική πρόβλεψη επιμέρους αγορών.'});\n  else notes.push({title:'Σενάρια',body:'Το ισόπαλο, η ανατροπή ή η διατήρηση του σκορ εξαρτώνται από τον χρόνο, τα γεγονότα και τη δυναμική του αγώνα. Χωρίς αξιόπιστα στοιχεία δεν δίνουμε κατασκευασμένα ποσοστά.'});\n }else if(forecast){\n  const vals=[forecast.p1,forecast.px,forecast.p2],j=vals.indexOf(Math.max(...vals));\n  notes.push({title:'Ισορροπία 1Χ2',body:'Το '+['προβάδισμα της γηπεδούχου','ενδεχόμενο ισοπαλίας','προβάδισμα της φιλοξενούμενης'][j]+' έχει τη μεγαλύτερη μοντελοποιημένη πιθανότητα ('+pct(vals[j])+'). Παραμένει εκτίμηση, όχι βέβαιο αποτέλεσμα.'});\n  if(num(m.mu_home)!==null&&num(m.mu_away)!==null)notes.push({title:'Ρυθμός γκολ',body:'Η ιστορική προσαρμογή Poisson δίνει μέση παραγωγή '+m.mu_home.toFixed(2)+' / '+m.mu_away.toFixed(2)+' γκολ. Over 2.5: '+pct(m.over25)+' · GG: '+pct(m.btts)+'.'});\n  notes.push({title:tierLabel(m),body:evidenceNote(m)});\n }else{\n  notes.push({title:'Τι γνωρίζουμε',body:'Πραγματική αναμέτρηση '+m.home+' – '+m.away+' στη διοργάνωση '+lname(m.league)+', '+dateFmt(m.date,'full')+' στις '+clock(m.date)+'.'});\n  notes.push({title:'Τι λείπει',body:'Δεν υπάρχουν αρκετά επαληθευμένα ιστορικά δεδομένα και των δύο ομάδων για προσωποποιημένες πιθανότητες 1Χ2, Over ή GG.'});\n  notes.push({title:'Ιστορική βάση',body:evidenceNote(m)});\n }\n return notes.map((n,i)=>'<article class=\"intelligence-note\"><span class=\"note-count\">0'+(i+1)+'</span><div><strong>'+esc(n.title)+'</strong><p>'+esc(n.body)+'</p></div></article>').join('');\n}\nfunction liveDetailPanel(m){\n if(!inProgress(m))return '';\n const events=Array.isArray(m.events)?m.events:[],stats=Array.isArray(m.statistics)?m.statistics:[],lineups=Array.isArray(m.lineups)?m.lineups:[];\n const names={BALL_POSSESSION:'Κατοχή μπάλας',SHOTS_TOTAL:'Σουτ',SHOTS_ON_TARGET:'Σουτ στον στόχο',CORNER_KICKS:'Κόρνερ',FOULS:'Φάουλ',YELLOWCARDS:'Κίτρινες κάρτες',RED_CARDS:'Κόκκινες κάρτες'};\n const ids={home:m.home_id,away:m.away_id};\n const rows=Object.entries(names).map(([type,label])=>{\n  const h=stats.find(x=>x.type===type&&x.participant_id===ids.home),a=stats.find(x=>x.type===type&&x.participant_id===ids.away);\n  return h||a?'<div class=\"analysis-stat\"><b>'+esc(h?.value??'—')+'</b><span>'+esc(label)+'</span><b>'+esc(a?.value??'—')+'</b></div>':'';\n }).filter(Boolean).join('');\n const items=events.slice(-14).reverse().map(e=>'<li><time>'+esc(e.minute??'—')+'′</time><span>'+esc(e.type||'Γεγονός')+(e.player?' · '+esc(e.player):'')+'</span></li>').join('');\n const starters=team=>lineups.filter(x=>x.team_id===team).slice(0,11).map(x=>(x.number?x.number+' · ':'')+x.player).join(', ');\n const home=starters(ids.home),away=starters(ids.away);\n if(!rows&&!items&&!home&&!away)return '<p class=\"analysis-muted\">Δεν έχουν διατεθεί ακόμη αναλυτικά γεγονότα ή στατιστικά από τον πάροχο.</p>';\n return '<div class=\"analysis-facts\">'+(rows?'<section><h3>Στατιστική αναμέτρησης</h3><div class=\"analysis-stats\">'+rows+'</div></section>':'')+\n  (items?'<section><h3>Χρονολόγιο αγώνα</h3><ol class=\"analysis-events\">'+items+'</ol></section>':'')+\n  (home||away?'<section><h3>Αρχικές ενδεκάδες</h3>'+(home?'<p><b>'+esc(m.home)+'</b> · '+esc(home)+'</p>':'')+(away?'<p><b>'+esc(m.away)+'</b> · '+esc(away)+'</p>':'')+'</section>':'')+'</div>';\n}\nfunction showModal(id,refresh=false){\n const m=state.all.find(x=>String(x.id)===String(id));if(!m)return;\n const old=$('.modal'),scroll=old?.scrollTop||0;\n if(!refresh)state.modalRestore=document.activeElement;\n state.selectedId=String(id);\n const live=inProgress(m),p=live?liveForecast(m):valid(m)?m:null;\n const nums=p?[p.p1,p.px,p.p2]:[null,null,null],max=nums.every(v=>num(v)!==null)?Math.max(...nums):null;\n const modelSource=live?liveForecastSource(m):valid(m)?tierLabel(m):'ΧΩΡΙΣ ΤΕΚΜΗΡΙΩΜΕΝΗ ΑΡΙΘΜΗΤΙΚΗ ΠΡΟΒΛΕΨΗ';\n const label=(key,val)=>'<div class=\"intel-metric\"><small>'+esc(key)+'</small><b>'+esc(pct(val))+'</b></div>';\n const bestScore=live?m.live_outlook?.most_likely_final:m.most_likely_score;\n const over=live?m.live_outlook?.over25:m.over25,under=live?m.live_outlook?.under25:m.under25,gg=live?m.live_outlook?.btts:m.btts;\n const next=live&&m.live_outlook?.next_goal;\n const mast='<div class=\"intel-mast\"><span class=\"intel-kicker\">'+esc(lname(m.league))+'</span>'+\n  '<span class=\"intel-tag'+(live?' on-air':'')+'\">'+(live?'● LIVE '+(num(m.minute)!==null?m.minute+'′':''):esc(clock(m.date)))+'</span></div>';\n const teams='<div class=\"intel-teams\"><div class=\"intel-team\">'+crest(m.home,'featured-crest',m.logos?.home)+'<strong>'+esc(m.home)+'</strong></div>'+\n  '<div class=\"intel-center\"><b>'+(live&&num(m.home_score)!==null?esc(m.home_score+' : '+m.away_score):'VS')+'</b><small>'+esc(dateFmt(m.date,'weekday'))+'</small></div>'+\n  '<div class=\"intel-team\">'+crest(m.away,'featured-crest',m.logos?.away)+'<strong>'+esc(m.away)+'</strong></div></div>';\n const probabilities='<div class=\"intel-section-head\"><h3>'+(live?'Πιθανή τελική έκβαση':'Ανάλυση τελικού αποτελέσματος')+'</h3><span>'+esc(modelSource)+'</span></div>'+\n  (p?'<div class=\"intel-1x2\">'+nums.map((v,i)=>'<div class=\"intel-outcome'+(max===v?' emphasis':'')+'\"><span>'+['1 · '+m.home,'Χ · Ισοπαλία','2 · '+m.away][i].replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</span><b>'+esc(pct(v))+'</b><div class=\"intel-track\"><i style=\"width:'+Math.min(100,Math.max(0,v))+'%\"></i></div></div>').join('')+'</div>':\n  '<div class=\"intel-absence\">Δεν δημοσιεύουμε ποσοστά χωρίς αντιστοιχισμένα ιστορικά στοιχεία ή live δεδομένα του παρόχου.</div>');\n const markets='<div class=\"intel-section-head\"><h3>Γκολ & σενάρια</h3><span>'+(live?'ΜΕ ΒΑΣΗ ΤΟ ΤΡΕΧΟΝ ΣΚΟΡ':'PRE-MATCH ESTIMATE')+'</span></div>'+\n  '<div class=\"intel-markets\">'+label('Over 2.5',over)+label('Under 2.5',under)+label('GG / BTTS',gg)+\n  '<div class=\"intel-metric\"><small>Πιθανότερο τελικό σκορ</small><b>'+esc(bestScore?.score||'—')+'</b>'+(num(bestScore?.probability)!==null?'<span>'+pct(bestScore.probability)+'</span>':'')+'</div></div>'+\n  (next?'<div class=\"intel-next\"><strong>Ποιος μπορεί να σκοράρει το επόμενο γκολ;</strong><div>'+\n   label(m.home,next.home)+label(m.away,next.away)+label('Κανένα άλλο γκολ',next.none)+'</div></div>':'');\n const body='<div class=\"intel-section-head\"><h3>Τι μπορεί να συμβεί;</h3><span>ΕΡΜΗΝΕΙΑ ΔΕΔΟΜΕΝΩΝ</span></div><div class=\"intel-narrative\">'+insightNarrative(m)+'</div>';\n const details=live?'<div class=\"intel-section-head\"><h3>Δεδομένα αγώνα σε εξέλιξη</h3><span>SPORTMONKS EVENTS</span></div>'+liveDetailPanel(m):'';\n const caveat='<div class=\"intel-caveat\">Η ανάλυση είναι πειραματική, δεν προβλέπει με βεβαιότητα μελλοντικά γεγονότα και δεν αποτελεί στοιχηματική σύσταση. Οι μέσοι όροι πρωταθλημάτων δεν αποτελούν τεκμηριωμένη πρόβλεψη για συγκεκριμένη ομάδα. '+\n  (live&&m.live_outlook?'Το live Poisson δεν λαμβάνει υπόψη αποβολές, τραυματισμούς, αλλαγές και καθυστερήσεις. ':'')+\n  'Όπου δεν υπάρχει επαρκής τεκμηρίωση εμφανίζεται «—» αντί για κατασκευασμένα ποσοστά.</div>';\n $('#modalMount').innerHTML='<div class=\"modal-backdrop\" data-close-backdrop=\"1\"><section class=\"modal intel-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalTitle\">'+\n  '<div class=\"modal-header intel-modal-head\"><div><span class=\"section-kicker\">TIKI-DATA · MATCH INTELLIGENCE</span><h2 id=\"modalTitle\">Ανάλυση αγώνα</h2></div><button class=\"modal-close\" data-close-modal=\"1\" aria-label=\"Κλείσιμο\">×</button></div>'+\n  '<div class=\"modal-body intel-body\">'+mast+teams+probabilities+markets+body+details+caveat+'</div></section></div>';\n document.body.style.overflow='hidden';\n if(refresh){$('.modal').scrollTop=scroll;}else $('[data-close-modal]').focus();\n}\nfunction closeModal(){if(!$('#modalMount').innerHTML)return;$('#modalMount').innerHTML='';state.selectedId=null;document.body.style.overflow='';state.modalRestore?.focus?.({preventScroll:true})}\nlet popTimeout=0;function notice(title,body){const el=$('#actionPopover');el.innerHTML='<strong>'+esc(title)+'</strong><p>'+esc(body)+'</p>';el.hidden=!el.hidden}\ndocument.addEventListener('click',e=>{const l=e.target.closest('[data-league]');if(l){setLeague(l.dataset.league);return}const d=e.target.closest('[data-day]');if(d){setDay(d.dataset.day);return}const q=e.target.closest('[data-quick]');if(q){setMode(q.dataset.quick);return}const f=e.target.closest('[data-favorite]');if(f){toggleFavorite(f.dataset.favorite);return}const o=e.target.closest('[data-open]');if(o){showModal(o.dataset.open);return}if(e.target.closest('#spotDetails')||e.target.closest('#statsAnalyze')){showModal(state.featuredId);return}if(e.target.closest('[data-reset-filters]')){resetAllFilters();return}if(e.target.closest('#refreshBtn')){fetchFixtures();return}if(e.target.closest('#loadMore')){state.limit+=100;renderTable();return}if(e.target.closest('#todayBtn')){const first=filteredBase()[0];setDay(first?kt(first.date):'all');return}if(e.target.closest('#notifyBtn')){notice('Ειδοποιήσεις','Δεν έχει συνδεθεί υπηρεσία ειδοποιήσεων. Οι προβλέψεις ενημερώνονται με βάση τα διαθέσιμα ιστορικά δεδομένα.');return}if(e.target.closest('#profileBtn')){notice('Guest access','Μπορείς να δεις αγώνες και να κρατήσεις αγαπημένα σε αυτή τη συσκευή, χωρίς σύνδεση.');return}if(e.target.hasAttribute('data-close-modal')||e.target.hasAttribute('data-close-backdrop')){closeModal();return}});\nconst desktopPick=$('#desktopDatePick');if(desktopPick)desktopPick.addEventListener('change',e=>{const key=e.target.value;if(/^\\d{4}-\\d{2}-\\d{2}$/.test(key))setDay(key);else setDay('all')});\nconst searchInput=$('#globalSearch');if(searchInput){searchInput.value=IS_PREDICTIONS?String(params.get('q')||''):'';if(IS_PREDICTIONS){searchInput.addEventListener('input',e=>{state.query=e.target.value.trim().toLocaleLowerCase();state.day='all';state.limit=100;syncSearch();update()})}else{searchInput.placeholder='Αναζήτηση στις προβλέψεις…';searchInput.addEventListener('keydown',e=>{if(e.key==='Enter'&&searchInput.value.trim()){location.href='/predictions?q='+encodeURIComponent(searchInput.value.trim())}})}}\nconst visibleSearch=$('#fixtureSearch');if(visibleSearch){\n visibleSearch.value=state.query;\n visibleSearch.addEventListener('input',e=>{state.query=e.target.value.trim().toLocaleLowerCase();state.day='all';state.limit=100;syncSearch();update()});\n}\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#actionPopover').hidden=true}else if(e.key==='Tab'&&$('#modalMount').innerHTML){const nodes=$$('button:not(:disabled)', $('#modalMount'));if(!nodes.length)return;if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes[nodes.length-1].focus()}else if(!e.shiftKey&&document.activeElement===nodes[nodes.length-1]){e.preventDefault();nodes[0].focus()}}});\ndocument.addEventListener('error',e=>{const im=e.target;if(!im||im.tagName!=='IMG')return;if(im.classList.contains('league-image')){const p=im.parentElement;if(p){p.classList.remove('has-real-logo');if(!p.querySelector('.league-fallback')){const f=document.createElement('span');f.className='league-fallback';f.textContent=p.dataset.short||'⚽';p.append(f);}}im.remove();return;}if(im.classList.contains('team-logo-image')){const parent=im.parentElement;im.remove();if(parent&&!parent.querySelector('img.team-logo-image')){parent.classList.remove('has-team-logo');parent.classList.add('team-no-logo')}return;}if(im.classList.contains('logo-image'))im.remove();else if(im.classList.contains('logo-fallback'))im.replaceWith(document.createTextNode('⚽'))},true);\nif(IS_PREDICTIONS)$('a[href=\"/predictions\"]', $('.bottom-nav'))?.setAttribute('aria-current','page');else $('a[href=\"/\"]', $('.bottom-nav'))?.setAttribute('aria-current','page');\n$('#year').textContent=String(new Date().getFullYear());\nupdate();fetchFixtures();if(IS_PREDICTIONS){void refreshLive();setInterval(()=>{void refreshLive()},30000);setInterval(()=>{if(!document.hidden&&!$('#modalMount')?.innerHTML)void fetchFixtures()},240000)}\n})();";
const HOME="/* Tiki-Data homepage controller. Intentionally independent of predictions/table DOM. */\n(() => {\n  'use strict';\n\n  const $ = id => document.getElementById(id);\n  if (!$('featured') || !$('upcomingGrid')) return;\n\n  const logos = window.TIKI_LOGO_CATALOG || { teams: {}, leagues: {} };\n  const teams = new Map();\n  const shortTeams = new Map();\n  const esc = value => String(value ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n  const normalize = value => String(value || '').normalize('NFKD').replace(/[\\u0300-\\u036f]/g, '').replace(/[^\\p{L}\\p{N}]+/gu, ' ').trim().toLowerCase();\n  const shortName = value => normalize(value).replace(/\\b(?:fc|afc|cf|sc|ac)\\b/g, '').replace(/\\s+/g, ' ').trim();\n  const safeLogo = url => typeof url === 'string' && /^https:\\/\\/(?:raw\\.githubusercontent\\.com|media\\.api-sports\\.io)\\//.test(url) ? url : null;\n  const aliases = new Map([['olympiacos piraeus','olympiakos piraeus'],['olympiacos','olympiakos piraeus']]);\n  for (const [name, url] of Object.entries(logos.teams || {})) {\n    const safe = safeLogo(url);\n    if (!safe) continue;\n    teams.set(normalize(name), safe);\n    const short = shortName(name);\n    if (!shortTeams.has(short)) shortTeams.set(short, safe);\n    else if (shortTeams.get(short) !== safe) shortTeams.set(short, null);\n  }\n\n  const leagues = {\n    ucl: ['UEFA Champions League','UCL'], uel: ['UEFA Europa League','UEL'],\n    uecl: ['UEFA Conference League','UECL'], epl: ['Premier League','PL'],\n    laliga: ['La Liga','LL'], bundesliga: ['Bundesliga','BL'],\n    seriea: ['Serie A','SA'], ligue1: ['Ligue 1','L1'],\n    greece: ['Greek Super League','GSL'], cyprus: ['Cyprus First Division','CYP']\n  };\n  const leagueName = key => leagues[key]?.[0] || String(key || 'Διοργάνωση').replace(/[_-]/g, ' ');\n  const leagueAbbr = key => leagues[key]?.[1] || String(key || '').slice(0,3).toUpperCase();\n  const number = n => typeof n === 'number' && Number.isFinite(n) ? n : null;\n  const probability = n => number(n) == null ? '—' : n.toLocaleString('el-GR', { maximumFractionDigits:1 }) + '%';\n  const validModel = m => !!m && [m.p1,m.px,m.p2].every(n => number(n) !== null && n >= 0 && n <= 100) && Math.abs(m.p1 + m.px + m.p2 - 100) < 2;\n  const formatter = {\n    weekday: new Intl.DateTimeFormat('el-GR', { weekday:'short', day:'numeric', month:'short' }),\n    full: new Intl.DateTimeFormat('el-GR', { weekday:'long', day:'numeric', month:'long' }),\n    time: new Intl.DateTimeFormat('el-GR', { hour:'2-digit', minute:'2-digit', hour12:false })\n  };\n  const day = (date, type='weekday') => formatter[type].format(new Date(date));\n  const time = date => formatter.time.format(new Date(date));\n  const icon = name => {\n    const paths = {\n      info: '<circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 11v6M12 7h.01\"/>',\n      chevron: '<path d=\"m9 18 6-6-6-6\"/>',\n      calendar: '<rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M7 3v4M17 3v4M3 10h18\"/>',\n      alert: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v6m0 4h.01\"/>'\n    };\n    return '<svg class=\"ui-icon\" aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">' + (paths[name] || paths.info) + '</svg>';\n  };\n  const fallbackImage = name => {\n    const initials = String(name || 'FC').replace(/\\b(fc|cf|sc|ac|afc|sv|club)\\b/gi,'').trim().split(/\\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase() || 'FC';\n    const svg = '<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><circle cx=\"32\" cy=\"32\" r=\"29\" fill=\"#19455a\" stroke=\"#70d8bb\" stroke-width=\"2\"/><text x=\"32\" y=\"40\" text-anchor=\"middle\" font-size=\"19\" font-family=\"Arial,sans-serif\" font-weight=\"bold\" fill=\"#d9fff1\">' + esc(initials) + '</text></svg>';\n    return 'data:image/svg+xml,' + encodeURIComponent(svg);\n  };\n  const crest = (name, className='table-crest') => {\n    const key = normalize(name);\n    const url = teams.get(key) || teams.get(aliases.get(key)) || shortTeams.get(shortName(name));\n    return '<span class=\"'+esc(className)+'\" title=\"'+esc(name)+'\"><img class=\"logo-fallback\" src=\"'+fallbackImage(name)+'\" alt=\"\" loading=\"lazy\" />' +\n      (url ? '<img class=\"logo-image\" src=\"'+esc(url)+'\" alt=\"\" loading=\"lazy\" decoding=\"async\" referrerpolicy=\"no-referrer\"/>' : '') + '</span>';\n  };\n  const leagueIcon = (code, className='small-league') => {\n    const url = safeLogo(logos.leagues?.[code]);\n    return '<span class=\"'+esc(className)+'\" title=\"'+esc(leagueName(code))+'\">' + esc(leagueAbbr(code)) +\n      (url ? '<img class=\"logo-image league-image\" src=\"'+esc(url)+'\" alt=\"\" loading=\"lazy\" decoding=\"async\" referrerpolicy=\"no-referrer\"/>' : '') + '</span>';\n  };\n  const renderText = (id, value) => { const node=$(id); if (node) node.textContent=String(value); };\n  const renderHTML = (id, value) => { const node=$(id); if (node) node.innerHTML=value; };\n  const setBusy = (busy) => {\n    document.body.classList.toggle('is-loading', busy);\n    for (const id of ['featured','spotPred','spotMarkets','statsCompare','upcomingGrid']) {\n      const node=$(id);\n      if (node) node.setAttribute('aria-busy',String(busy));\n    }\n  };\n\n  let matches = [];\n  let featured = null;\n  let inFlight = null;\n  let modalPreviousFocus = null;\n\n  function renderSummary(list) {\n    renderText('metricMatches',list.length);\n    renderText('metricLeagues',new Set(list.map(m=>m.league)).size);\n    renderText('metricAnalyses',list.filter(validModel).length);\n    for (const id of ['metricMatches','metricLeagues','metricAnalyses']) $(id)?.removeAttribute('aria-hidden');\n  }\n\n  function marketCell(name, value, best=false) {\n    return '<div class=\"market'+(best?' strongest':'')+'\"><small>'+esc(name)+'</small><b>'+esc(probability(value))+'</b></div>';\n  }\n  function preferred(a,b) {\n    return number(a) !== null && number(b) !== null && a >= 0 && a <= 100 && b >= 0 && b <= 100 && a !== b ? a>b?0:1 : -1;\n  }\n  function renderFeatured(match) {\n    featured = match || null;\n    const details = $('spotDetails'), analyse = $('statsAnalyze');\n    if (details) details.disabled=!match;\n    if (analyse) analyse.disabled=!match;\n    if (!match) {\n      renderText('spotLabel','NO UPCOMING MATCH');\n      renderText('spotLeague','Δεν υπάρχει προγραμματισμένος αγώνας');\n      renderText('spotDate','—');\n      renderHTML('spotHome',crest('','featured-crest')+'<b>—</b>');\n      renderHTML('spotAway',crest('','featured-crest')+'<b>—</b>');\n      renderHTML('spotPred','<div class=\"feature-prob muted\">'+icon('info')+' Δεν υπάρχουν προσεχείς αγώνες για ανάλυση.</div>');\n      renderHTML('spotMarkets','');\n      renderText('statsHome','HOME');\n      renderText('statsAway','AWAY');\n      renderHTML('statsCompare','<p class=\"stats-note\">Η σύγκριση θα εμφανιστεί όταν υπάρχει διαθέσιμος αγώνας.</p>');\n      return;\n    }\n    renderHTML('spotLeague',leagueIcon(match.league)+'<span>'+esc(leagueName(match.league))+'</span>');\n    renderText('spotDate',day(match.date)+' · '+time(match.date));\n    renderText('spotLabel',validModel(match)?'MODEL AVAILABLE':'UPCOMING');\n    renderHTML('spotHome',crest(match.home,'featured-crest')+'<b>'+esc(match.home)+'</b>');\n    renderHTML('spotAway',crest(match.away,'featured-crest')+'<b>'+esc(match.away)+'</b>');\n    if (validModel(match)) {\n      const values=[match.p1,match.px,match.p2],best=Math.max(...values);\n      renderHTML('spotPred',values.map((p,i)=>'<div class=\"feature-prob'+(p===best?' best strongest':'')+'\"><div><small>'+['1','X','2'][i]+'</small><b>'+esc(probability(p))+'</b></div><span class=\"track\"><i style=\"width:'+Math.max(0,Math.min(p,100))+'%\"></i></span></div>').join(''));\n    } else {\n      renderHTML('spotPred','<div class=\"feature-prob muted\">'+icon('info')+' Δεν υπάρχουν επαρκή δεδομένα για πιθανότητες 1Χ2.</div>');\n    }\n    const ou=preferred(match.over25,match.under25), bt=preferred(match.btts,match.no_btts);\n    renderHTML('spotMarkets',marketCell('Over 2.5',match.over25,ou===0)+marketCell('Under 2.5',match.under25,ou===1)+marketCell('BTTS · Ναι',match.btts,bt===0)+marketCell('BTTS · Όχι',match.no_btts,bt===1));\n    renderText('statsHome',match.home);\n    renderText('statsAway',match.away);\n    const stats=[['Αναμενόμενα γκολ',match.mu_home,match.mu_away],['Κατοχή μπάλας',null,null],['Σουτ στον στόχο',null,null]];\n    renderHTML('statsCompare',stats.map(([label,l,r])=>{\n      const available=number(l)!==null&&number(r)!==null, total=available?l+r:0, left=total>0?Math.round(100*l/total):50;\n      return '<div class=\"stat-row\"><span class=\"stat-val\">'+(available?l.toFixed(2):'—')+'</span><div class=\"stat-row-mid\"><span>'+esc(label)+'</span><div class=\"stat-track\"><i style=\"width:'+(available?left:0)+'%\"></i><b style=\"width:'+(available?100-left:0)+'%\"></b></div></div><span class=\"stat-val\">'+(available?r.toFixed(2):'—')+'</span></div>';\n    }).join(''));\n  }\n\n  function renderUpcoming(soon) {\n    const target=$('upcomingGrid');\n    if (!target) return;\n    if (!soon.length) {\n      target.innerHTML='<div class=\"upcoming-empty\" role=\"status\">'+icon('info')+'<span>Δεν υπάρχουν καταχωρισμένοι προσεχείς αγώνες.</span><a href=\"/predictions\">Προβολή προγράμματος</a></div>';\n      return;\n    }\n    target.innerHTML=soon.slice(0,3).map(m=>{\n      const good=validModel(m), values=[m.p1,m.px,m.p2], top=good?Math.max(...values):null;\n      const win=top===null?'Δεν υπάρχει ανάλυση':['1','X','2'][values.indexOf(top)]+' · '+probability(top);\n      return '<button class=\"upcoming-card\" data-open=\"'+esc(m.id)+'\" type=\"button\" aria-label=\"Ανάλυση '+esc(m.home)+' εναντίον '+esc(m.away)+'\"><span class=\"upcoming-card-head\"><span class=\"upcoming-competition\">'+leagueIcon(m.league)+'<span>'+esc(leagueName(m.league))+'</span></span><time datetime=\"'+esc(m.date)+'\">'+esc(day(m.date))+' · '+esc(time(m.date))+'</time></span><span class=\"upcoming-teams\"><span class=\"upcoming-side\">'+crest(m.home)+'<b>'+esc(m.home)+'</b></span><span class=\"upcoming-vs\">VS</span><span class=\"upcoming-side away\">'+crest(m.away)+'<b>'+esc(m.away)+'</b></span></span><span class=\"upcoming-card-foot\"><span>Εκτίμηση μοντέλου</span><strong class=\"'+(top===null?'no-prediction':'')+'\">'+esc(win)+'</strong><span class=\"upcoming-arrow\">'+icon('chevron')+'</span></span></button>';\n    }).join('');\n  }\n\n  function renderError(reason) {\n    renderText('metricMatches','—');\n    renderText('metricLeagues','—');\n    renderText('metricAnalyses','—');\n    for(const id of ['metricMatches','metricLeagues','metricAnalyses']) $(id)?.removeAttribute('aria-hidden');\n    renderFeatured(null);\n    renderText('spotLabel','DATA UNAVAILABLE');\n    const info='<div class=\"upcoming-empty\" role=\"alert\">'+icon('alert')+'<span>Δεν ήταν δυνατή η φόρτωση των αγώνων. Δοκίμασε ξανά.</span><button class=\"load-more\" type=\"button\" data-retry-home=\"1\">Επανάληψη</button></div>';\n    renderHTML('upcomingGrid',info);\n    console.error('[Tiki-Data] Homepage data failed:',reason);\n  }\n  function safeRender(label,fn) {\n    try { fn(); return true; }\n    catch (error) { console.error('[Tiki-Data] '+label,error); return false; }\n  }\n\n  async function fetchFixtures() {\n    if (inFlight) return inFlight;\n    setBusy(true);\n    const controller=new AbortController();\n    const timeout=setTimeout(()=>controller.abort(),15000);\n    inFlight=(async()=>{\n      try {\n        const response=await fetch('/api/fixtures',{headers:{Accept:'application/json'},cache:'no-store',signal:controller.signal});\n        if (!response.ok) throw new Error('HTTP '+response.status);\n        const body=await response.json();\n        if (!body || !Array.isArray(body.matches)) throw new Error('Invalid matches[] response');\n        matches=body.matches.filter(m=>m&&m.id!=null&&m.home&&m.away&&m.date&&Number.isFinite(Date.parse(m.date))).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));\n        const now=Date.now();\n        const future=matches.filter(m=>Date.parse(m.date)>=now);\n        safeRender('summary',()=>renderSummary(matches));\n        safeRender('featured',()=>renderFeatured(future.find(validModel)||future[0]||null));\n        safeRender('upcoming',()=>renderUpcoming(future.slice(0,3)));\n        document.body.dataset.tikiDataState='ready';\n        document.dispatchEvent(new CustomEvent('tiki:home-ready',{detail:{matches:matches.length,upcoming:future.length}}));\n      } catch (error) {\n        document.body.dataset.tikiDataState='error';\n        safeRender('error UI',()=>renderError(error));\n      } finally {\n        clearTimeout(timeout);\n        inFlight=null;\n        setBusy(false);\n      }\n    })();\n    return inFlight;\n  }\n\n  function modalOpen(id) {\n    const match=matches.find(m=>String(m.id)===String(id));\n    if (!match || !$('modalMount')) return;\n    modalPreviousFocus=document.activeElement;\n    const values=validModel(match)?[match.p1,match.px,match.p2]:[null,null,null];\n    const best=values.every(x=>x!==null)?Math.max(...values):null;\n    const market=(key,val)=>'<div class=\"modal-cell\"><small>'+esc(key)+'</small><b>'+esc(probability(val))+'</b></div>';\n    const goals=(key,val)=>'<div class=\"modal-cell\"><small>'+esc(key)+'</small><b>'+(number(val)===null?'—':esc(val.toFixed(2)))+'</b></div>';\n    const scorelines=Array.isArray(match.scorelines)?match.scorelines.slice(0,4):[];\n    renderHTML('modalMount','<div class=\"modal-backdrop\" data-close-backdrop=\"1\"><section class=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalTitle\"><div class=\"modal-header\"><div><span class=\"section-kicker\">'+esc(leagueName(match.league))+'</span><h2 id=\"modalTitle\">Ανάλυση αγώνα</h2></div><button type=\"button\" class=\"modal-close\" data-close-modal=\"1\" aria-label=\"Κλείσιμο\">×</button></div><div class=\"modal-body\"><div class=\"modal-teams\"><div class=\"modal-team\">'+crest(match.home,'featured-crest')+esc(match.home)+'</div><span class=\"modal-vs\">VS</span><div class=\"modal-team\">'+crest(match.away,'featured-crest')+esc(match.away)+'</div></div><div class=\"modal-date\">'+esc(day(match.date,'full'))+' · '+esc(time(match.date))+'</div><div class=\"modal-section\">ΠΙΘΑΝΟΤΗΤΕΣ 1 / Χ / 2</div><div class=\"modal-probs\">'+values.map((v,i)=>'<div class=\"modal-cell'+(v!==null&&v===best?' best':'')+'\"><small>'+['1 · Γηπεδούχος','X · Ισοπαλία','2 · Φιλοξενούμενος'][i]+'</small><b>'+esc(probability(v))+'</b></div>').join('')+'</div><div class=\"modal-section\">ΑΝΑΛΥΣΗ ΓΚΟΛ</div><div class=\"modal-other\">'+market('Over 2.5',match.over25)+market('Under 2.5',match.under25)+market('BTTS Ναι',match.btts)+market('BTTS Όχι',match.no_btts)+goals('xG Home',match.mu_home)+goals('xG Away',match.mu_away)+'</div>'+(scorelines.length?'<div class=\"modal-section\">ΠΙΘΑΝΑ ΣΚΟΡ</div><div class=\"modal-other\">'+scorelines.map(x=>market(x.score,x.prob)).join('')+'</div>':'')+'<p class=\"modal-disclaimer\">Πειραματικές πιθανότητες βάσει μοντέλου Poisson. Δεν αποτελεί εγγύηση αποτελέσματος ή στοιχηματική σύσταση.</p></div></section></div>');\n    document.body.style.overflow='hidden';\n    $('modalMount').querySelector('[data-close-modal]')?.focus();\n  }\n  function modalClose() {\n    const node=$('modalMount');\n    if (!node || !node.innerHTML) return;\n    node.innerHTML='';\n    document.body.style.overflow='';\n    modalPreviousFocus?.focus?.({preventScroll:true});\n  }\n  function showNotice(title,message) {\n    const node=$('actionPopover');\n    if (!node) return;\n    node.innerHTML='<strong>'+esc(title)+'</strong><p>'+esc(message)+'</p>';\n    node.hidden=false;\n  }\n\n  document.addEventListener('click',event=>{\n    const clicked=event.target.closest?.('[data-open],#spotDetails,#statsAnalyze,[data-close-modal],[data-close-backdrop],[data-retry-home],#notifyBtn,#profileBtn');\n    if (!clicked) return;\n    if (clicked.matches('[data-open]')) modalOpen(clicked.dataset.open);\n    else if (clicked.matches('#spotDetails,#statsAnalyze') && featured) modalOpen(featured.id);\n    else if (clicked.matches('[data-close-modal],[data-close-backdrop]')) modalClose();\n    else if (clicked.matches('[data-retry-home]')) void fetchFixtures();\n    else if (clicked.id==='notifyBtn') showNotice('Ειδοποιήσεις','Δεν υπάρχει ενεργή υπηρεσία ειδοποιήσεων.');\n    else if (clicked.id==='profileBtn') showNotice('Guest access','Η αναζήτηση και οι προβλέψεις είναι διαθέσιμες χωρίς λογαριασμό.');\n  });\n  document.addEventListener('keydown',event=>{\n    if (event.key==='Escape') { modalClose(); if ($('actionPopover')) $('actionPopover').hidden=true; }\n    if (event.key==='Tab' && $('modalMount')?.innerHTML) {\n      const buttons=[...$('modalMount').querySelectorAll('button:not(:disabled)')];\n      if (!buttons.length) return;\n      if (event.shiftKey && document.activeElement===buttons[0]) { event.preventDefault();buttons.at(-1).focus(); }\n      else if (!event.shiftKey && document.activeElement===buttons.at(-1)) { event.preventDefault();buttons[0].focus(); }\n    }\n  });\n  document.addEventListener('error',event=>{\n    const img=event.target;\n    if (img?.tagName==='IMG' && img.classList.contains('logo-image')) img.remove();\n  },true);\n  const search=$('globalSearch');\n  if (search) {\n    search.placeholder='Αναζήτηση στις προβλέψεις…';\n    search.addEventListener('keydown',event=>{\n      if (event.key==='Enter' && search.value.trim()) location.href='/predictions?q='+encodeURIComponent(search.value.trim());\n    });\n  }\n  document.querySelector('.bottom-nav a[href=\"/\"]')?.setAttribute('aria-current','page');\n  renderText('year',new Date().getFullYear());\n  void fetchFixtures();\n})();\n";
