 for(let i=0;i<x.length;i++)for(let j=0;j<y.length;j++){const v=x[i]*y[j];sum+=v;if(i>j)one+=v;else if(i===j)draw+=v;else two+=v;if(i+j>2)over+=v;if(i>0&&j>0)gg+=v;}
